function App() {
  const [form, setForm] = useState({ email: '', password: '' });
  const [errors, setErrors] = useState({});
  const handleChange = e => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };
  const validate = () => {
    const next = {};
    if (!/^[^@]+@[^@]+\.[^@]+$/.test(form.email)) next.email = 'Enter a valid email';
    if (form.password.length < 6) next.password = 'Min 6 characters';
    return next;
  };
  const handleSubmit = e => {
    e.preventDefault();
    const next = validate();
    setErrors(next);
    if (Object.keys(next).length === 0) alert('Logged in as ' + form.email);
  };
  return (
    <form onSubmit={handleSubmit} style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input name="email" value={form.email} onChange={handleChange} placeholder="Email" />
      {errors.email && <p style={{ color: 'red' }}>{errors.email}</p>}
      <input name="password" type="password" value={form.password} onChange={handleChange} placeholder="Password" />
      {errors.password && <p style={{ color: 'red' }}>{errors.password}</p>}
      <button type="submit">Log in</button>
    </form>
  );
}
